<?php $title='Boutique'; $subtitle='Gérez vos produits, vos stocks et les ventes au comptoir.'; $section='shop'; require __DIR__.'/management_header.php'; ?>
<div class="management-grid"><?php if ($canSell): ?><details class="card form-card" <?= $error && ($_POST['action'] ?? '')==='sale' ? 'open' : '' ?>><summary>+ Enregistrer une vente</summary><form method="post" action="index.php?page=shop" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="sale"><label>Produit *<select name="product_id" required><option value="">Sélectionner</option><?php foreach ($products as $p): if (!$p['is_active']) continue; ?><option value="<?= (int)$p['id'] ?>" <?= (string)$p['id']===($_POST['product_id'] ?? '')?'selected':'' ?>><?= e($p['name'].' · '.dt($p['price']).' · stock '.$p['stock']) ?></option><?php endforeach; ?></select></label><label>Quantité *<input type="number" name="quantity" min="1" max="1000000" value="<?= e(($_POST['action'] ?? '')==='sale' ? ($_POST['quantity'] ?? '1') : '1') ?>" required></label><label>Moyen de paiement *<select name="method"><?php foreach (['espèces','chèque','virement','D17','Flouci','carte bancaire'] as $method): ?><option value="<?= e($method) ?>" <?= ($_POST['method'] ?? '')===$method?'selected':'' ?>><?= e(ucfirst($method)) ?></option><?php endforeach; ?></select></label><p class="form-hint">Une vente porte sur un seul produit. Le prix affiché est figé lors de l’enregistrement.</p><div class="form-actions"><button class="primary">Valider la vente</button></div></form></details><?php endif; ?>
<?php if ($canManage): ?><details class="card form-card" <?= $error && ($_POST['action'] ?? '')==='product' ? 'open' : '' ?>><summary>+ Ajouter un produit</summary><form method="post" action="index.php?page=shop" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="product"><label>Nom *<input name="name" maxlength="120" required value="<?= e($_POST['name'] ?? '') ?>"></label><label>Référence unique *<input name="sku" maxlength="50" required value="<?= e($_POST['sku'] ?? '') ?>"></label><label>Prix unitaire (DT) *<input type="number" name="price" min="0" max="9999999.999" step="0.001" required value="<?= e($_POST['price'] ?? '') ?>"></label><label>Stock initial *<input type="number" name="stock" min="0" max="1000000" required value="<?= e($_POST['stock'] ?? '0') ?>"></label><label>Seuil d’alerte *<input type="number" name="threshold" min="0" max="1000000" required value="<?= e($_POST['threshold'] ?? '5') ?>"></label><div class="form-actions"><button class="primary">Créer le produit</button></div></form></details><details class="card form-card" <?= $error && ($_POST['action'] ?? '')==='restock' ? 'open' : '' ?>><summary>+ Réapprovisionner</summary><form method="post" action="index.php?page=shop" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="restock"><label>Produit *<select name="product_id" required><option value="">Sélectionner</option><?php foreach ($products as $p): if (!$p['is_active']) continue; ?><option value="<?= (int)$p['id'] ?>"><?= e($p['name'].' · stock '.$p['stock']) ?></option><?php endforeach; ?></select></label><label>Quantité reçue *<input type="number" name="quantity" min="1" max="1000000" required></label><div class="form-actions"><button class="primary">Ajouter au stock</button></div></form></details><?php endif; ?></div>
<section class="card management-table"><div class="card-head"><div><h3>Catalogue & stocks</h3><p>L’alerte apparaît lorsque le stock atteint ou descend sous son seuil.</p></div></div><div class="table-scroll"><table><thead><tr><th>PRODUIT</th><th>RÉFÉRENCE</th><th>PRIX</th><th>STOCK</th><th>SEUIL</th><th>ÉTAT</th></tr></thead><tbody><?php foreach ($products as $p): ?><tr><td><strong><?= e($p['name']) ?></strong></td><td><?= e($p['sku']) ?></td><td><?= e(dt($p['price'])) ?></td><td><?= (int)$p['stock'] ?></td><td><?= (int)$p['low_stock_threshold'] ?></td><td><span class="status <?= !$p['is_active'] || (int)$p['stock'] <= (int)$p['low_stock_threshold'] ? 'expired' : '' ?>"><?= !$p['is_active'] ? 'Inactif' : ((int)$p['stock']===0 ? 'Rupture' : ((int)$p['stock'] <= (int)$p['low_stock_threshold'] ? 'Stock bas' : 'Disponible')) ?></span></td></tr><?php endforeach; ?><?php if (!$products): ?><tr><td colspan="6" class="empty">Aucun produit pour le moment.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="card management-table"><div class="card-head"><div><h3>Ventes boutique</h3><p><?= $total ?> vente(s) · <?= e(date('d/m/Y',strtotime($date))) ?></p></div><strong class="cash-total"><?= e(dt($salesTotal)) ?></strong></div><form class="search-form" method="get"><input type="hidden" name="page" value="shop"><label for="shop-date">Date</label><input id="shop-date" type="date" name="date" value="<?= e($date) ?>"><button class="primary">Afficher</button></form><div class="table-scroll"><table><thead><tr><th>HEURE</th><th>PRODUIT</th><th>QUANTITÉ</th><th>PRIX UNIT.</th><th>TOTAL</th><th>MOYEN</th><th>VENDEUR</th></tr></thead><tbody><?php foreach ($sales as $sale): ?><tr><td><?= e(date('H:i',strtotime($sale['sold_at']))) ?></td><td><?= e($sale['name']) ?></td><td><?= (int)$sale['quantity'] ?></td><td><?= e(dt($sale['unit_price'])) ?></td><td><?= e(dt($sale['total'])) ?></td><td><?= e(ucfirst($sale['method'])) ?></td><td><?= e($sale['seller'] ?: '—') ?></td></tr><?php endforeach; ?><?php if (!$sales): ?><tr><td colspan="7" class="empty">Aucune vente pour cette date.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php if ($pageNumber>1): ?><a href="index.php?page=shop&amp;date=<?= e($date) ?>&amp;p=<?= $pageNumber-1 ?>">← Précédent</a><?php endif; ?><span>Page <?= $pageNumber ?> / <?= max(1,(int)ceil($total/10)) ?></span><?php if ($pageNumber*10<$total): ?><a href="index.php?page=shop&amp;date=<?= e($date) ?>&amp;p=<?= $pageNumber+1 ?>">Suivant →</a><?php endif; ?></div><p class="form-hint">Ces ventes sont séparées de la caisse des abonnements et ne sont pas encore incluses dans les revenus du tableau de bord.</p></section>
<?php require __DIR__.'/management_footer.php'; ?>
